/// <summary>
/// PricingAttribute of table <c>CustTable</c> field PaymDayId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTablePaymDayId extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, PaymDayId);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    CustTable   custTable;

    while select PaymDayId from custTable
        group by PaymDayId
    {
        ret.add(custTable.PaymDayId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, PaymDayId));
    qbr.value(queryValue(_value));
}
